// Generated by @canonical/summon-component:react v0.43.0

import {
  createEnvironment,
  setPrefetchEnvironment,
} from "@canonical/prism-core";
import { createMemoryAdapter, createRouter } from "@canonical/router-core";
import { RouterProvider } from "@canonical/router-react";
import { render, screen } from "@testing-library/react";
import { RelayEnvironmentProvider } from "react-relay";
import type { FetchFunction } from "relay-runtime";
import { afterEach, describe, expect, it } from "vitest";
import { MESSAGES } from "#i18n";
import { Shell } from "#lib/ui";
import { appRoutes, notFoundRoute } from "../../../../routes.js";
import HomePage from "./HomePage.js";

afterEach(() => {
  setPrefetchEnvironment(undefined);
});

/** A network that never answers, so the doors stay suspended. */
const neverAnswer: FetchFunction = () => new Promise<never>(() => {});

/** Render the site at `/` over a network that answers through `fetchFn`. */
const renderLanding = (fetchFn: FetchFunction): void => {
  const environment = createEnvironment({ fetchFn });
  setPrefetchEnvironment(environment);
  render(
    <Shell
      environment={environment}
      router={createRouter(appRoutes, {
        adapter: createMemoryAdapter("/"),
        notFound: notFoundRoute,
      })}
    />,
  );
};

describe("HomePage", () => {
  it("keeps its heading standing while the counts are on their way", async () => {
    renderLanding(neverAnswer);
    expect(
      await screen.findByText(MESSAGES["home.loading"]),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("heading", { level: 1, name: MESSAGES["home.title"] }),
    ).toBeInTheDocument();
    expect(screen.getByText(MESSAGES["home.lead"])).toHaveClass("lead");
  });

  it("says so when the counts cannot be read", async () => {
    renderLanding(() => Promise.reject(new Error("the graph is down")));
    expect(await screen.findByRole("alert")).toHaveTextContent(
      MESSAGES["home.error"],
    );
  });

  it("is a section labelled by its heading", async () => {
    renderLanding(neverAnswer);
    const section = await screen.findByRole("region", {
      name: MESSAGES["home.title"],
    });
    expect(section.className).toBe("ds home-page");
  });

  it("passes native props through and merges a consumer className after its own", () => {
    render(
      <RelayEnvironmentProvider
        environment={createEnvironment({ fetchFn: neverAnswer })}
      >
        <RouterProvider
          router={createRouter(appRoutes, {
            adapter: createMemoryAdapter("/"),
          })}
        >
          <HomePage className="is-quiet" data-testid="landing" />
        </RouterProvider>
      </RelayEnvironmentProvider>,
    );
    expect(screen.getByTestId("landing").className).toBe(
      "ds home-page is-quiet",
    );
  });
});
